NAME = 'Est: Estonian Bible'
BOOK = 'I Peter'

CHAPTERS = {
    1: {
        1: 'Peetrus, Jeesuse Kristuse Apostel, Pontoses, Galaatias, Kapadookias, Aasias ja Bitüünias hajuvil asuvaile valitud majalistele,',
        2: 'Jumala Isa etteteadmist mööda Vaimu pühitsemise kaudu sõnakuulmiseks ja piserdamiseks Jeesuse Kristuse Verega! Arm ja rahu rohkenegu teile!',
        3: 'Kiidetud olgu Jumal ja meie Issanda Jeesuse Kristuse Isa, Kes Oma suurt halastust mööda meid on uuesti sünnitanud elavaks lootuseks Jeesuse Kristuse ülestõusmise läbi surnuist',
        4: 'kadumatu ja rüvetamatu ja närtsimatu pärandi saamiseks, mis taevas on tallel teie jaoks,',
        5: 'mida Jumala väega valvatakse usu läbi õndsuse jaoks, mis on valmis ilmsiks tulema viimsel ajal!',
        6: 'Sellest te väga rõõmutsete, kuigi te nüüd vajaduse korral pisut kurvastute mõnesugustes kiusatustes,',
        7: 'et teie usk, kui see on läbi katsutud, leitaks kallihinnalisem olevat kullast, mis kaob ja siiski tules läbi katsutakse, ja oleks teile kiituseks ja hiilguseks ja auks Jeesuse Kristuse ilmumisel,',
        8: 'Keda te küll ei ole näinud, ja siiski armastate, Kellesse te nüüd usute, kuigi te Teda ei näe, ja rõõmutsete ütlematu ning väga kalli rõõmuga,',
        9: 'kes saavutate usu eesmärgi, hingede õndsuse.',
        10: 'Seda õndsust on uurinud ja juurelnud prohvetid, kes on ennustanud teile määratud armust,',
        11: 'juureldes seda, mis ja millise aja kohta teateid andis Kristuse Vaim nende sees, kui Ta ette ilmutas Kristust tabavaid kannatusi ja neile järgnevaid austusi.',
        12: 'Neile ilmutati, et mitte neile endile, vaid teile oli kasuks see, mis nüüd on kuulutatud teile nende kaudu, Kes teile taevast läkitatud Püha Vaimu läbi on toonud Evangeeliumi; ja sellesse igatsevad Inglidki vaadata.',
        13: 'Sellepärast vöötage oma meele niuded ja olge kained; ja lootke täiesti armu peale, mida teile pakutakse Jeesuse Kristuse ilmumises.',
        14: 'Kui sõnakuulelikkuse lapsed ärge anduge endistele himudele, nagu siis kui teil puudus õige teadmine;',
        15: 'vaid nõnda nagu See, Kes teid on kutsunud, on püha, saage ka ise pühaks kõigis eluviisides;',
        16: 'sest on kirjutatud: "Olge pühad, sest Mina olen püha!"',
        17: 'Ja et te appi hüüate teda kui Isa, Kes isikule vaatamata mõistab kohut igaühe tegu mööda, siis veetke kartuses oma majaliseks olemise aeg,',
        18: 'teades, et teid ei ole kaduvaga, hõbeda või kullaga lunastatud teie tühiseist esivanemailt päritud eluviisidest,',
        19: 'vaid Kristuse kui veatu ja laitmatu talle kalli Verega,',
        20: 'Kes küll oli ette määratud enne maailma rajamist, aga aegade lõpul on saanud ilmsiks teie pärast,',
        21: 'kes Tema kaudu olete usklikud Jumalasse, kes Tema surnuist üles äratas ja Temale andis au, nii et teie usk on ka lootus Jumala peale.',
        22: 'Et te olete oma hinged puhastanud tõe sõnakuulmises teesklematuks vennalikuks armastuseks, siis armastage üksteist innukalt ja südamest,',
        23: 'sest et olete uuesti sünnitatud mitte kaduvast, vaid kadumatust seemnest, Jumala elava ning püsiva sõna läbi.',
        24: 'Sest "kõik liha on nagu rohi ja kõik tema hiilgus nagu rohu õieke; rohi kuivab ära ja õieke variseb maha,',
        25: 'aga Issanda sõna püsib igavesti!" Ja see on see sõna, mis teile rõõmusõnumina on kuulutatud.',
    },
    2: {
        1: 'Siis pange nüüd maha kõik kurjus ja kõik kavalus ja silmakirjatsus ja kadedus ja kõik keelekandmine',
        2: 'ning himustage otsekui vastsündinud lapsed vaimset täispiima, et te selle läbi võiksite kasvada õndsuseks,',
        3: 'kui te olete maitsnud, et Issand on helde, tulles Tema juurde',
        4: 'kui elava kivi juurde, mis küll inimeste poolt on põlatud, aga Jumala juures on ära valitud ja väga kallis,',
        5: 'ja teiegi ehituge üles kui elavad kivid vaimulikuks kojaks ja pühaks preesterkonnaks ohverdama vaimulikke ohvreid, mis on Jumalale meelepärased Jeesuse Kristuse kaudu.',
        6: 'Sellepärast ongi lugeda Kirjas: "Vaata, Mina panen Siionisse valitud kalli nurgakivi, ja kes Temasse usub, see ei satu häbisse!"',
        7: 'Teile nüüd, kes usute, on Ta kallihinnaline; aga uskmatuile on Ta "kivi, mille hooneehitajad põlgasid, kuid mis sai nurgakiviks",',
        8: 'ja "komistuskiviks ja pahanduskaljuks". Nemad "tõukavad Tema vastu", sest nad ei kuule sõna, ja selleks on need ka pandud.',
        9: 'Teie aga olete "valitud sugu, kuninglik preesterkond, püha rahvas, omandrahvas, et te kuulutaksite Tema aulisi tegusid", Kes teid on kutsunud pimedusest Oma imelise valguse juurde,',
        10: 'teie, kes muiste olite "mitterahvas", aga nüüd olete Jumala rahvas; kes "ei olnud armu saanud", aga nüüd olete armu saanud!',
        11: 'Armsad, ma manitsen teid kui "võõraid ja majalisi" hoiduda lihalikest himudest, mis sõdivad hinge vastu,',
        12: 'ja elada vooruslikku elu paganate keskel, et nad selles, mille pärast nad teist kui kurjategijaist paha räägivad, teie häid tegusid nähes annaksid Jumalale austust "katsumispäeval"!',
        13: 'Alistuge kõigele inimeste seatud korrale Issanda pärast, olgu kuningale kui ülemale valitsejale,',
        14: 'või pealikuile kui neile, keda tema on läkitanud kurjategijaile nuhtluseks, aga heategijaile kiituseks.',
        15: 'Sest nõnda on Jumala tahtmine, et teie, tehes head, tõkestaksite mõistmatute inimeste rumalust -',
        16: 'kui vabad ja mitte kui need, kellele vabadus on kurjuse katteks, vaid kui Jumala sulased.',
        17: 'Austage kõiki, armastage vendi, kartke Jumalat, austage kuningat!',
        18: 'Sulased, olge kõige kartusega allaheitlikud oma isandaile, mitte ainult headele ja leplikele, vaid ka tigedaile.',
        19: 'Sest see on arm, kui keegi südametunnistuse pärast Jumala ees talub viletsusi, kannatades süütult.',
        20: 'Sest mis kiitus see on, kui teid pekstakse patu pärast ning te jääte kannatlikuks? Aga kui te head tehes ja kurja kannatades püsite kannatlikena, siis on see arm Jumala juures.',
        21: 'Selleks te ju olete kutsutud, sest et Kristuski kannatas teie eest ja jättis teile eeskuju, et te käiksite Tema jälgedes,',
        22: '"kes ei teinud pattu ja Kelle suust ei leitud pettust",',
        23: 'Kes ei sõimanud vastu, kui Teda sõimati, Kes ei ähvardanud, kui Ta kannatas, vaid jättis selle hooleks, Kes mõistab kohut õigesti,',
        24: 'Kes meie patud ise kandis üles ristipuule Oma ihus, et meie pattudele ära sureksime ja elaksime õigusele, Kelle vermete tõttu te olete terveks saanud.',
        25: 'Sest te olite "nagu eksijad lambad", aga nüüd te olete pöördunud oma hingede Karjase ja Hooldaja poole.',
    },
    3: {
        1: 'Samuti teie, naised, olge allaheitlikud oma meestele, et ka need, kes ei ole sõnakuulelikud sõnale, naiste eluviiside läbi võidetaks ilma sõnata usule,',
        2: 'kui nad vaatavad, kuidas te elate jumalakartuses puhast elu.',
        3: 'Teie ehteks ärgu olgu välispidine juuste palmitsemine, kulla ümberriputamine ega toredate riietega riietumine,',
        4: 'vaid varjul olev südame inimene, tasase ja vaikse vaimu kadumatuses, mis on kallis Jumala ees.',
        5: 'Sest nõnda on ka ennevanasti pühad naised, kes lootsid Jumala peale, endid ehtinud ja olnud allaheitlikud oma meestele,',
        6: 'nõnda nagu Saara oli sõnakuulelik Aabrahamile ja "hüüdis teda isandaks", ja tema lasteks te olete saanud, kui te teete head ega karda ühtki hirmutust.',
        7: 'Samuti teie, mehed, elage naisega targasti kui nõrgema astjaga ja osutage neile austust, sest nad on elu armuanni kaaspärijad nagu teiegi, et teie palved poleks tagajärjeta.',
        8: 'Aga viimaks, olge kõik üksmeelsed, kaastundlikud, vennaarmastajad, halastajad, alandlikud!',
        9: 'Ärge tasuge kurja kurjaga ega sõimu sõimuga, vaid vastupidi, õnnistage, sest te teate, et olete kutsutud pärima õnnistust!',
        10: 'Sest "kes armastab elu ja näha häid päevi, see hoidku oma keelt kurja eest ja oma huuli pettust rääkimast;',
        11: 'ta pöördugu ära kurjast ning tehku head; ta otsigu rahu ja nõudku seda taga.',
        12: 'Sest Issanda silmad on õigete poole ja tema kõrvad nende palvetamise poole; aga Issanda pale on pahategijate vastu!"',
        13: 'Ja kes peaks teile kurja tegema, kui te heategemises olete agarad?',
        14: 'Aga kuigi te kannataksite õiguse pärast, siis olete ometi õndsad. "Ärge kartke nende hirmutamist ja ärge kohkuge",',
        15: 'vaid pühitsege Issandat Kristust oma südameis, olles alati valmis andma vastust igaühele, kes teilt nõuab seletust lootuse kohta, mis teis on.',
        16: 'Aga vastake tasaduse ja kartusega, ja teil olgu hea südametunnistus, et jääksid häbisse selles, mida teist paha räägivad need, kes teotavad teie head eluviisi Kristuses.',
        17: 'Sest parem on, kui nõnda on Jumala tahtmine, head tehes kannatada kui paha tehes.',
        18: 'On ju ka Kristus kord surnud pattude pärast, õige ülekohtuste eest, et Ta meid juhiks Jumala juurde, kui Ta küll surmati liha poolest, kuid elavaks tehti vaimu poolest,',
        19: 'kelles Ta ka läks ära ja kuulutas vangis olevaile vaimudele,',
        20: 'kes muiste ei kuulanud sõna, kui Jumala pikk meel ootas Noa päevil, kui ehitati laeva, millel mõned üksikud, see on kaheksa hinge, päästeti läbi vee.',
        21: 'Sellele võrdluskujule vastavalt päästab teidki nüüd vesi ristimisena, mitte kui liha rüveduse kõrvaldamine, vaid kui hea südametunnistuse nõudmine Jumala ees Jeesuse Kristuse ülestõusmise kaudu,',
        22: 'Kes on läinud taevasse ja on Jumala paremal käel ja Kellele on alistatud Inglid ja võimud ja väed.',
    },
    4: {
        1: 'Et nüüd Kristus on kannatanud lihas, siis relvastuge teiegi sama meelega; sest kes lihas on kannatanud, see on lakanud pattu tegemast,',
        2: 'nõnda et ta aega, mis tal veel on elada lihas, enam ei ela inimeste himude järgi, vaid Jumala tahtmise järgi.',
        3: 'Sest sellest on küllalt, et teil möödunud aeg kulus ära paganate tahte täitmiseks, kui te elasite lodevuses, himudes, viinajoomises, öistes olenguis, jootudes ja jõledais ebajumalateenistustes.',
        4: 'Nemad võõrastavad seda, et teie nendega ühes ei jookse samas lodeva elu voolus, ning pilkavad teid.',
        5: 'Nad peavad aru andma Sellele, Kes on valmis kohut mõistma elavate ja surnute üle.',
        6: 'Sest selleks on surnuile kuulutatud Evangeelium, et kohus nende üle oleks mõistetud nagu inimeste üle lihas ja nad elaksid nagu Jumal vaimus.',
        7: 'Aga kõigi asjade lõpp on lähedal! Olge siis mõistlikud ja kained palveiks!',
        8: 'Kõigepealt olgu teie armastus südamlik üksteise vastu, sest "armastus katab pattude hulga".',
        9: 'Olge külalislahked üksteise vastu ilma nurisemata.',
        10: 'Teenigu igaüks teist selle andega, mille ta on saanud, kui Jumala mõnesuguse armu head majapidajad.',
        11: 'Kui keegi räägib, siis ta rääkigu kui Jumala sõnu; kui keegi teenib, siis ta teenigu kui jõust, mida Jumal annab, et kõiges austataks Jumalat Jeesuse Kristuse läbi, Kelle on au ja vägi ajastute ajastuteni! Aamen.',
        12: 'Armsad, ärge pidage võõraks tulekuumust enestes, mis teile on saanud katsumiseks, otsekui sünniks teile midagi võõrast,',
        13: 'vaid sedamööda nagu teil on osa Kristuse kannatamistest, olge rõõmsad, et võiksite rõõmustuda ning hõisata Tema au ilmumisel.',
        14: 'Kui teid solvatakse Kristuse nime pärast, siis te olete õndsad, sest au ja Jumala Vaim hingab teie peal.',
        15: 'Ärgu siis keegi teist kannatagu mõrtsukana või vargana või kurjategijana või salakaebajana.',
        16: 'Aga kui keegi kannatab ristiinimesena, siis ta ärgu häbenegu, vaid andku Jumalale austust selle nimega.',
        17: 'Sest aeg on kohtul alata Jumala kojast; kui see aga algab kõigepealt meist, missugune ots ootab neid, kes ei ole sõnakuulelikud Jumala Evangeeliumile?',
        18: 'Ja kui õige vaevalt pääseb, kuhu siis saab õel ja patune?',
        19: 'Seepärast usaldagu need, kes Jumala tahtmise järgi kannatavad, oma hinged ustava Looja hooleks, tehes head.',
    },
    5: {
        1: 'Kogudusevanemaid teie seas ma nüüd manitsen kui kaasvanem ja Kristuse kannatuste tunnistaja, kes ka olen tulevase au osaline, mis peab ilmuma:',
        2: 'hoidke teile hoida antud Jumala karja mitte sundusest, vaid vabast tahtest Jumala meele järgi, mitte alatu kasu tõttu, vaid innust,',
        3: 'mitte isandaina valitsedes kogudusi kui liisuosi, vaid olles karjale eeskujuks;',
        4: 'siis te saate, kui Ülimkarjane ilmub, närtsimatu aupärja!',
        5: 'Samuti teie, nooremad, alistuge vanemaile ja riietuge kõik alandlikkusega üksteise vastu; sest "Jumal paneb suurelistele vastu, aga alandlikele Ta annab armu!"',
        6: 'Siis alanduge Jumala vägeva käe alla, et Ta teid ülendaks omal ajal!',
        7: 'Heitke kõik oma mure Tema peale, sest Tema peab hoolt teie eest!',
        8: 'Olge kained, valvake, sest teie vastane, kurat, käib ümber nagu möirgaja lõukoer otsides, keda neelata!',
        9: 'Tema vastu seiske kindlad usus ning teadke, et teie vendadel maailmas tuleb neidsamu kannatusi täielikult kanda.',
        10: 'Aga kõige armu Jumal Ise, Kes meid on kutsunud Oma igavesse ausse Kristuses, võtku teid, kui te pisut olete kannatanud, valmistada, kinnitada, teha tugevaks ja rajada!',
        11: 'Tema päralt on võimus ajastute ajastuteni! Aamen.',
        12: 'Silvaanuse, minu arvates ustava venna kaudu olen teile lühidalt kirjutanud, manitsedes ja tunnistades, et see on tõeline Jumala arm, milles te olete.',
        13: 'Teid tervitab kaasvalitud kogudus Baabülonis ja Markus, mu poeg.',
        14: 'Tervitage üksteist armastuse suudlusega! Rahu teile kõikidele, kes olete Kristuses!',
    },
}
